<?php if ( ! defined('BASEPATH')) exit('No direct script access allowed');class mbuyerbrand extends CI_Controller {    private $limit = 10;    public function __construct() {        parent::__construct();        error_reporting(0);        $this->load->model(CNFCOMPANY."mbuyermodel");        $this->load->helper('cookie');        $this->load->helper('xssclean');        $this->load->library('email');        $this->load->helper('email');        $this->load->helper('common');        fnIfCheckUserLoggedIn();    }    public function addedit() {        $ArrData												= array('ArrBasicInfo'=>array(),'VarId'=>'','VarNew'=>0,'brands'=>'');        $VarHashId		    									= $this->uri->segment(4);        if($VarHashId <>'' && base64_decode(urldecode($VarHashId))) {            $VarId                                              = base64_decode(urldecode($VarHashId));            $ArrResults     									= $this->mbuyermodel->fnGetInfo('',$VarId);            $ArrData['VarId']					                = $ArrResults['buyer'][0]->id;            $ArrData['buyer']					                = $ArrResults['buyer'];            $ArrData['brands']					                =       $ArrResults['brands'];        } else {            $ArrData['VarNew']  							    = 1;        }        $this->load->view(CNFCOMPANY.'addeditbuyer',$ArrData);    }    public function updateBuyerInfo() {        $VarUserInfo = fnGetUserLoggedInfo(1);        if(isset($VarUserInfo['companyid'])) {            $VarCompanyId = $VarUserInfo['companyid'];        }        $ArrResult                                              = array();        /*        $VarExtraBrands  										= xssclean($this->input->post('frmExtraBrands'));        $VarNewBrands  										    = xssclean($this->input->post('newBrands'));        $VarBrands  										= xssclean($this->input->post('GlbfrmBrands'));        $ArrBrandIds = array();        if(isset($frmBrandIds) && $frmBrandIds <> '') {            $ArrBrandIds = explode(",",$frmBrandIds);        }        $ArrBrands = array();        if($VarExtraBrands <> '' && isset($VarExtraBrands)) {            $ArrBrands = explode(",",$VarExtraBrands);        }        $ArrKeyCombined = array_combine($ArrBrandIds,$ArrBrands);*/        $VarBuyer				    					        = xssclean($this->input->post('by'));        $VarBra				    					        = xssclean($this->input->post('bra'));        //$VarBrand				    					        = xssclean($this->input->post('frmDefaultBrand'));        //$VarDefaultBrand                                        = xssclean($this->input->post('frmDefaultBrandId'));        $VarCompany				    					        = xssclean($this->input->post('cn'));        $VarEmail				    					        = xssclean($this->input->post('e'));        $VarMobile				    					        = xssclean($this->input->post('m'));        $VarPhone				    					        = xssclean($this->input->post('p'));        $VarAddress				    					        = xssclean($this->input->post('a'));        $VarDesignation				    					        = xssclean($this->input->post('d'));        $VarStatus												= xssclean($this->input->post('s'));        $VarId       											= xssclean($this->input->post('id'));        $VarUpdatedBy											= fnGetUserLoggedInfo();        if($VarBuyer<>'') {            $ArrBuyerData                                      = array('id'=>$VarId,'buyername'=>$VarBuyer,'brandname'=>$VarBra,'companyid'=>$VarCompanyId,                'companyname'=>$VarCompany,'emailid'=>$VarEmail,'mobileno'=>$VarMobile,'phoneno'=>$VarPhone,'address'=>$VarAddress,'designation'=>$VarDesignation,                'status'=>$VarStatus,'dateupdated'=>date('Y-m-d H:i:s'));            /*$ArrBrandData = array('id'=>$VarDefaultBrand,'default'=>$VarBrand,'ArrBrands'=>$ArrKeyCombined,'VarNewBrands'=>$VarNewBrands);*/            if($VarId=='' || $VarId==0) {                $ArrBuyerData['datecreated']                   = date('Y-m-d H:i:s');            }            $ArrStatus                                          = $this->mbuyermodel->saveBuyerInfo($ArrBuyerData);            echo json_encode($ArrStatus);unset($ArrStatus);unset($ArrUpdateData);die;        } else {            $ArrResult['errcode']							    = '-1';            $ArrResult['msg']								    = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function manage() {        $VarFrom												= xssclean($this->input->post('rfrom'));        $VarBuyer										        = xssclean($this->input->post('buyer'));        $VarStatus										        = xssclean($this->input->post('s'));        if($VarFrom==1) {            $VarURLSegment										= 4;            $this->load->library('pagination');            $config['base_url']									= base_url().CNFCOMPANY.'mbuyerbrand/manage/';            $config['total_rows']								= $this->mbuyermodel->fnCountBuyer($VarBuyer,$VarStatus);            $config['per_page']									= 10;            $config['uri_segment']								= $VarURLSegment;            $offset												= $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby												= "dateupdated";            $sortorder											= "desc";            $ArrLabList								            = $this->mbuyermodel->fnListBuyer($VarBuyer,$VarStatus,$this->limit,$offset,$sortby,$sortorder)->result();            $data['pagination']									= $this->pagination->create_linkswithajax('Buyers');            $i=0;            $ArrFnlList										    = array();            $ArrStatus                                          = unserialize(ARRSTATUS);            foreach ($ArrLabList as $ObjUnit){                $ArrId[]						    = $ObjUnit->id;            }            //$ArrBrands						    = $this->mbuyermodel->fnGetBrands($ArrId);            foreach ($ArrLabList as $ObjUnit){                $ArrFnlList[$i]['id']						    = $ObjUnit->id;                $ArrFnlList[$i]['bran']						    = $ObjUnit->brandname;                $ArrFnlList[$i]['buyer']						    = $ObjUnit->buyername;                $ArrFnlList[$i]['s']						    = $ArrStatus[$ObjUnit->status];                $ArrFnlList[$i]['companyname']						    = $ObjUnit->companyname;                $i=$i+1;            }            //$ArrFnlList['brands'] = $ArrBrands;            echo json_encode(array('errcode'=>1,'cn'=>$config['total_rows'],'ct'=>$i,'re'=>$ArrFnlList,'pa'=>base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY.'managebuyer');        }    }    function delBuyerInfo() {        $VarBuyerId                                             = xssclean($this->input->post('id'));        $VarUpdatedBy                                         = fnGetUserLoggedInfo();        if($VarBuyerId>=1) {            $ArrResult             					          = $this->mbuyermodel->fnDelBuyer($VarBuyerId,$VarUpdatedBy);        } else {            $ArrResult['errcode']						      = -1;            $ArrResult['msg']							      = '';        }        echo json_encode($ArrResult);    }}